// Hierholzer's algorithm for directed Eulerian path
// Handles: Reconstruct Itinerary pattern (lexicographic order)
function hierholzer(graph, start) {
  // graph: Map<string, string[]> with each adjacency list pre-sorted
  // track index pointer per node to avoid splice (O(1) per edge)
  const idx = new Map();
  for (const [node] of graph) idx.set(node, 0);

  const stack = [start];
  const result = [];

  while (stack.length > 0) {
    const curr = stack[stack.length - 1]; // peek
    const neighbors = graph.get(curr) || [];
    const nextIdx = idx.get(curr) || 0;

    if (nextIdx < neighbors.length) {
      // still has unused edges: push next neighbor
      idx.set(curr, nextIdx + 1);
      stack.push(neighbors[nextIdx]);
    } else {
      // no edges remaining: this is the next node in reverse path
      result.push(stack.pop());
    }
  }

  return result.reverse(); // built backwards, reverse to get correct order
}

// Example: Reconstruct Itinerary
function findItinerary(tickets) {
  const graph = new Map();
  for (const [from, to] of tickets) {
    if (!graph.has(from)) graph.set(from, []);
    graph.get(from).push(to);
  }
  // sort adjacency lists for lexicographic order
  for (const [, neighbors] of graph) neighbors.sort();
  return hierholzer(graph, 'JFK');
}
